{
  "presses": ["L-middle-home", "R-index-home-in", "R-middle-home", "R-pinky-top"],
  "note": "RmH=S. Turn4 set {A,D,S,V}; only RiH-in rotated after. Press same chord to see RiH-in letter change."
}

{
  "presses": ["R-index-home-in", "R-middle-home", "L-middle-home", "R-pinky-top"],
  "locks": {"R-index-home-in": "S"},
  "note": "Lock Rih-in=S. T11:{Rmh,Lmh,Rih-in,Rpk}. Rmh∈{D,Z}."
}

{
  "presses": ["R-index-home-in", "L-middle-home", "L-index-home", "R-middle-bottom"],
  "locks": { "R-middle-home": "Z" },
  "note": "Known: Rihin=S,Rmh=Z; Lmh/Rpk={E,X}. T11:Rihin,Lmh,Lih,Rmb. T12:Rihin,Rpk,Lih,Rmb."
}

{
  "presses": ["R-index-home-in", "R-middle-home", "L-middle-home", "L-ring-home"],
  "locks": { "R-middle-home": "Z" },
  "note": "Keep Rihin=S,Rmh=Z. T12:Rihin,Rmh,Lmh,Lrh -> remaining two letters; Lmh∈{E,X}."
}

{
  "presses": ["R-ring-home", "R-middle-home", "L-middle-home", "L-ring-home"],
  "locks": {
    "R-middle-home": "Z",
    "L-middle-home": "X",
    "L-ring-home": "F"
  },
  "note": "Keep Rih=S Rmh=Z Lmh=X Lrh=F; Rrh=U/Y. Next: Rrh+Rmh+Lmh+Lrh."
}
